import { Component } from '@angular/core';
import { FormControl } from '@angular/forms';
import { combineLatest, map, Observable, startWith, switchMap, tap } from 'rxjs';
import { CountryService } from './country.service';
import { Country, State } from './types';

@Component({
  selector: 'app-exercise2',
  templateUrl: './exercise2.component.html',
  styleUrls: ['./exercise2.component.css'],
})
export class Exercise2Component {
  countries$: Observable<Country[]> = this.service.getCountries();
  countryDropdown = new FormControl<Country['id']>('');
  states$: Observable<State[]> = this.service.getStates('US');

  currentCountry$ = combineLatest([
    this.countries$,
    this.countryDropdown.valueChanges.pipe(startWith(this.countryDropdown.value))
  ]).pipe(map(([countries, countryID]) => {
    return countries.find((c) => c.id === countryID)?.id;
  }));

  statesList$ = this.currentCountry$.pipe(
    tap((c) => console.log),
    switchMap((countryID) => {
      console.log('countryID = ', countryID);
      return this.service.getStates(countryID);
    })
  );

  // currentCountry$ = combineLatest([
  //   this.states$,
  //   this.countryDropdown.valueChanges.pipe(startWith(this.countryDropdown.value))
  // ]).pipe(
  //   map(([states, countryID]) => {
  //     // console.log(countryID);
  //     // console.log(states);

  //     return states.filter((s) => {
  //       console.log(s.countryCode === countryID, s.countryCode, '  ', countryID);
  //       return s.countryCode === countryID
  //     });
  //   })
  // )

  constructor(private service: CountryService) {}

  getState(countryID: string) {
    return this.service.getStates(countryID);
  }
}
<h2>Exercise 2</h2>
<h3>
  Your mission is to connect the two following dropdowns so that the state/province dropdown gets populated with data
  from the selected country.
</h3>
<img src="assets/exercise2.gif" />
<ol>
  <li>
    Make sure that the state dropdown is disabled when no country is selected as well as when the selected country has
    no state information
  </li>
  <li>
    Update the code in <code>app/exercise2</code> so that our component loads its list of states from
    <code>http://localhost:3000/states?countryCode=US</code> and use the right country code as a parameter
  </li>
  <li>Display the total number of states (for the selected country) in the corresponding <code>div</code></li>
  <li>States should be displayed in alphabetical order and using title case</li>
  <li>Selecting a state should result in the <code>code</code> of the state being set as the dropdown value</li>
</ol>
<h4>
  You can take a look at the expected result here: <a routerLink="/solution/2">http://localhost:4200/solution/2</a>
</h4>
<hr />
<h2>Result</h2>
<div *ngIf="countries$ | async as countries">
  <div>Select one of {{ countries.length }} countries:</div>
  <select [formControl]="countryDropdown">
    <option disabled value="">--Select the country--</option>
    <option *ngFor="let country of countries" [value]="country.id">
      {{ country.description }}
    </option>
  </select>
  <div>Current value: {{ countryDropdown.value }}</div>
</div>


<ng-container *ngIf="statesList$ | async as statesList">
  <ng-container *ngIf="statesList.length > 0">
    <div>Select one of {{statesList.length}} states/provinces:</div>
    <select #statesDropdown>
      <option [value]="" *ngFor="let state of statesList; truckBy: truckById">State or province</option>
    </select>
    <div>Current value: {{ statesDropdown.value }}</div>

  </ng-container>

</ng-container>

<div>
  States {{currentCountry$ | async | json}}
  <!-- States {{statesList$ | async | json}} -->
</div>
